{
  "name": "Robo HAT MM1 电机控制板",
  "name_en": "Robo HAT MM1 Motor Controller",
  "manufacturer": "Robotics Masters",
  "description": "用于机器人与无人小车实验的车载控制板。该组件通过串口读取来自 SAMD51 的 RC/PWM 控制信号，并将其映射为归一化的转向与油门输出，适合 DonkeyCar 类平台的人为遥控与自动驾驶控制流程。",
  "description_en": "An onboard control board for robotics and autonomous RC car experiments. It reads RC/PWM control signals from a SAMD51 over serial and maps them to normalized steering and throttle outputs, suitable for DonkeyCar-like user-control and autonomous driving workflows.",
  "actions": [
    {
      "action_name": "auto-shutdown",
      "description": "关闭控制器并停止相关通信。",
      "description_en": "Shut down the controller and stop related communication."
    },
    {
      "action_name": "auto-read_serial",
      "description": "从串口读取转向和油门控制信号，并映射为归一化输出。",
      "description_en": "Read steering and throttle control signals from serial and map them to normalized outputs."
    },
    {
      "action_name": "auto-update",
      "description": "启动或执行持续更新流程，循环读取串口输入，并在启动时加入延时以避免异常。",
      "description_en": "Start or execute the continuous update loop, repeatedly reading serial input with a startup delay to avoid errors."
    },
    {
      "action_name": "auto-run",
      "description": "执行一次控制运行流程，可结合图像、模式和录制状态返回当前转向与油门。",
      "description_en": "Execute one control cycle and return current steering and throttle, optionally considering image, mode, and recording state."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "在线程化模式下返回当前转向与油门，并可应用默认模式或录制设置。",
      "description_en": "Return current steering and throttle in threaded mode, optionally applying default mode or recording settings."
    }
  ],
  "tag_hints": [
    "Robo HAT MM1",
    "RC car control",
    "serial PWM input",
    "steering and throttle mapping",
    "SAMD51 microcontroller",
    "DonkeyCar platform"
  ]
}

